-- Base de datos TiendaTech (datos ficticios). Se ejecuta sola al crear el contenedor de MySQL.
-- BD común del temario de Bases de Datos: pyme ficticia "TiendaTech" (datos inventados)
DROP TABLE IF EXISTS lineas_pedido, pedidos, productos, clientes, empleados, proveedores, categorias;
CREATE TABLE categorias (id_categoria INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(40) NOT NULL UNIQUE) ENGINE=InnoDB;
CREATE TABLE proveedores (id_proveedor INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(60) NOT NULL, ciudad VARCHAR(40), telefono VARCHAR(15)) ENGINE=InnoDB;
CREATE TABLE productos (id_producto INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(80) NOT NULL, id_categoria INT NOT NULL, id_proveedor INT NOT NULL,
  precio DECIMAL(8,2) NOT NULL CHECK (precio >= 0), stock INT NOT NULL DEFAULT 0 CHECK (stock >= 0), activo BOOLEAN NOT NULL DEFAULT TRUE,
  FOREIGN KEY (id_categoria) REFERENCES categorias(id_categoria), FOREIGN KEY (id_proveedor) REFERENCES proveedores(id_proveedor)) ENGINE=InnoDB;
CREATE TABLE clientes (id_cliente INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(40) NOT NULL, apellidos VARCHAR(60) NOT NULL, email VARCHAR(80) NOT NULL UNIQUE,
  ciudad VARCHAR(40), fecha_alta DATE NOT NULL) ENGINE=InnoDB;
CREATE TABLE empleados (id_empleado INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(40) NOT NULL, puesto VARCHAR(40) NOT NULL, salario DECIMAL(8,2) NOT NULL,
  id_jefe INT NULL, fecha_contratacion DATE NOT NULL, FOREIGN KEY (id_jefe) REFERENCES empleados(id_empleado)) ENGINE=InnoDB;
CREATE TABLE pedidos (id_pedido INT AUTO_INCREMENT PRIMARY KEY, id_cliente INT NOT NULL, id_empleado INT NULL, fecha DATE NOT NULL,
  estado ENUM('pendiente','enviado','entregado','cancelado') NOT NULL DEFAULT 'pendiente',
  FOREIGN KEY (id_cliente) REFERENCES clientes(id_cliente), FOREIGN KEY (id_empleado) REFERENCES empleados(id_empleado)) ENGINE=InnoDB;
CREATE TABLE lineas_pedido (id_pedido INT NOT NULL, num_linea INT NOT NULL, id_producto INT NOT NULL, cantidad INT NOT NULL CHECK (cantidad > 0),
  precio_unitario DECIMAL(8,2) NOT NULL, PRIMARY KEY (id_pedido, num_linea),
  FOREIGN KEY (id_pedido) REFERENCES pedidos(id_pedido) ON DELETE CASCADE, FOREIGN KEY (id_producto) REFERENCES productos(id_producto)) ENGINE=InnoDB;

