CREATE TABLE usuarios (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(30) NOT NULL UNIQUE, email VARCHAR(80) NOT NULL UNIQUE, hash VARCHAR(255) NOT NULL, rol ENUM('usuario','editor','admin') NOT NULL DEFAULT 'usuario') ENGINE=InnoDB;
CREATE TABLE reservas (id INT AUTO_INCREMENT PRIMARY KEY, nombre VARCHAR(60) NOT NULL, email VARCHAR(80) NOT NULL, personas TINYINT NOT NULL, fecha DATE NOT NULL, creada TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
